 49	\begin{lemma}[Evaluation identity for encoding outcomes]\label{lem:qld-decoder-evaluation}
 50		\lean{MIPStarRE.QPBT.decodeFq_dotProduct_indicatorVec}
 51		\leanok
 52		\uses{def:qld-full-field-decoder, def:indicator-vector}
 53		If $g$ is an encoding, then
 54		\[
 55			\mathrm{Dec}_{\F_q}(g)\cdot\mathrm{ind}_m(u)=g(u)
 56		\]
 57		for every $u\in\F_q^m$.
 58	\end{lemma}
 59	\begin{proof}
 60		\leanok
 61		\uses{def:qld-full-field-decoder, def:indicator-vector, def:low-degree-encoding}
 62		By \eqref{eq:low-degree-encoding-definition} the left-hand side is the value at $u$ of the multilinear encoding $g_{\mathrm{Dec}_{\F_q}(g)}$. Since $g$ is an encoding, that representative equals $g$, so the value is $g(u)$.
 63	\end{proof}
