340	\begin{lemma}[The marginals absorb the point measurements]\label{lem:qld-constructing-the-paulis-helper}
341		\lean{MIPStarRE.QPBT.sum_marginalPoly_pointMeas_approx_id}
342		\lean{MIPStarRE.QPBT.marginalPoly_sub_pointMeas_approx_zero}
343		\leanok
344		\uses{def:s-w-marginals, def:expanded-point-measurement, def:expanded-state, def:povm-distance, lem:qld-4-7, def:symmetric-equivalents}
345		For $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
346		\begin{equation}\label{eq:qld-sg-cons}
347			\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_P^{\mathrm{id}}} \Id
348		\end{equation}
349		and
350		\begin{equation}\label{eq:qld-sg-cons2}
351			\bigl(\hat{S}^W_g \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)})\bigr)_{\mathrm{A}\mathrm{A}'} \approx_{\delta_P^{\mathrm{ann}}} 0\;,
352		\end{equation}
353		where the answer summation is over $g \in \mathrm{ideg}_{d,m}(\F_q)$. The independently quantified scale $\delta_P^{\mathrm{ann}}$ includes the additional point-measurement error in \eqref{eq:qld-sg-cons2}. Furthermore, all symmetric equivalents of these approximations also hold (Definition~\ref{def:symmetric-equivalents}).
354	\end{lemma}
355	\begin{proof}
356		\uses{lem:qld-4-7, fact:agreement, fact:add-a-proj, def:bracket, lem:qld-comm-cons}
357		The point-consistency conclusion of Lemma~\ref{lem:qld-4-7} states that, on average over $u \in \F_q^m$,
358		\[
359			\bra{\hat\psi} \sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point}, W), u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \ket{\hat\psi} \geq 1 - \delta_G\;,
360		\]
361		which says exactly that the operator on the left-hand side of \eqref{eq:qld-sg-cons} is $\delta_G$-consistent with $\Id$; Lemma~\ref{fact:agreement} and the universal-factor enlargement give the $\approx_{\delta_P}$ statement \eqref{eq:qld-sg-cons}. For \eqref{eq:qld-sg-cons2}, the same consistency, written with the coarse-graining $\hat{S}^W_{[g(u)=a]} = \sum_{g : g(u) = a} \hat{S}^W_g$ as $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G)} (\hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{B}\mathrm{A}''}$ with answer summation over $a \in \F_q$, is left-multiplied by $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'}$ using Lemma~\ref{fact:add-a-proj}; moving $\hat{M}^{(\mathrm{Point}, W), u}_a$ from registers $\mathrm{B}\mathrm{A}''$ to $\mathrm{A}\mathrm{A}'$ costs a further $\eps$ by Cauchy--Schwarz together with the self-consistency of the $\hat{M}^{(\mathrm{Point}, W), u}_a$ (Lemma~\ref{lem:qld-comm-cons}), giving
362		\[
363			(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_G + \eps)} (\hat{S}^W_{[g(u)=a]} \cdot \hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{A}\mathrm{A}'}\;.
364		\]
365		Expanding
366		\[
367			\E_u \sum_g \bigl\| (\hat{S}^W_{g} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)}))_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi} \bigr\|^2
368			= \E_u \sum_a \bra{\hat\psi} \bigl((\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a}) \cdot \hat{S}^W_{[g(u)=a]} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a})\bigr)_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi}
369		\]
370		and bounding the right-hand side by $O(\delta_G + \eps)$ using the two approximations above yields \eqref{eq:qld-sg-cons2} at scale $\delta_P$. The symmetric equivalents follow by the same argument with the register bipartitions interchanged.
371	\end{proof}
